#include <iostream>
#include <algorithm>
using namespace std;

long long result = 0;

int digit_count(long long n) {
    int count = 0;
    while (n > 0) {
        n /= 10;
        count++;
    }
    return count;
}

long long get_threshold(long long n) {
    int digits = digit_count(n);
    long long threshold = 0, power = 1;
    for (int i = 0; i < digits; i++) {
        threshold += power;
        power *= 10;
    }
    if (threshold <= n) return threshold;
    return (threshold - 1) / 10;
}

long long solve(long long n) {
    if (n <= 6) return n;
    if (n <= 11) return 13 - n;
    long long base_value = get_threshold(n);
    long long limit = base_value * 10 + 1;
    if (n % base_value == 0) {
        long long quotient = n / base_value;
        if (n <= limit / 2 + base_value) return digit_count(base_value) * quotient;
        else {
            long long diff = solve(limit - n);
            return digit_count(limit) + diff;
        }
    } else {
        long long low = (n / base_value) * base_value;
        long long high = (n / base_value + 1) * base_value;
        long long total_res = solve(low) + solve(n - low);
        if (n > limit / 2) {
            total_res = min(solve(low) + solve(n - low), digit_count(limit) + solve(limit - n));
        }
        return total_res;
    }
}

int main() {
    long long n;
    cin >> n;
    cout << solve(n) << endl;
    return 0;
}
